// Package lru provides a fixed-capacity cache that evicts the least recently
// used entry. All operations run in O(1) expected time.
package lru

// entry is a node in the cache's intrusive doubly linked recency list.
type entry[K comparable, V any] struct {
	key        K
	value      V
	prev, next *entry[K, V]
}

// Cache is a least-recently-used cache. The zero value is not usable; create
// one with New. A Cache is not safe for concurrent use.
type Cache[K comparable, V any] struct {
	capacity int
	items    map[K]*entry[K, V]
	// root is a sentinel: root.next is the most recently used entry and
	// root.prev the least recently used one.
	root entry[K, V]
}

// maxInitialCapacity bounds the map preallocation so a huge capacity with few
// keys does not waste memory up front.
const maxInitialCapacity = 1 << 16

// New returns an empty cache holding at most capacity keys.
// It panics if capacity is less than 1.
func New[K comparable, V any](capacity int) *Cache[K, V] {
	if capacity < 1 {
		panic("lru: capacity must be positive")
	}
	c := &Cache[K, V]{
		capacity: capacity,
		items:    make(map[K]*entry[K, V], min(capacity, maxInitialCapacity)),
	}
	c.root.next = &c.root
	c.root.prev = &c.root
	return c
}

// Set inserts or overwrites the value for key, making it the most recently
// used. If the cache then exceeds its capacity, the least recently used key is
// evicted.
func (c *Cache[K, V]) Set(key K, value V) {
	if e, ok := c.items[key]; ok {
		e.value = value
		c.moveToFront(e)
		return
	}
	e := &entry[K, V]{key: key, value: value}
	c.items[key] = e
	c.pushFront(e)
	if len(c.items) > c.capacity {
		oldest := c.root.prev
		c.unlink(oldest)
		delete(c.items, oldest.key)
	}
}

// Get returns the value for key and whether it was present. A hit makes the
// key the most recently used.
func (c *Cache[K, V]) Get(key K) (V, bool) {
	e, ok := c.items[key]
	if !ok {
		var zero V
		return zero, false
	}
	c.moveToFront(e)
	return e.value, true
}

// Delete removes key and reports whether it was present.
func (c *Cache[K, V]) Delete(key K) bool {
	e, ok := c.items[key]
	if !ok {
		return false
	}
	c.unlink(e)
	delete(c.items, key)
	return true
}

// Len returns the number of keys held.
func (c *Cache[K, V]) Len() int {
	return len(c.items)
}

func (c *Cache[K, V]) pushFront(e *entry[K, V]) {
	e.prev = &c.root
	e.next = c.root.next
	c.root.next.prev = e
	c.root.next = e
}

func (c *Cache[K, V]) unlink(e *entry[K, V]) {
	e.prev.next = e.next
	e.next.prev = e.prev
	e.prev, e.next = nil, nil
}

func (c *Cache[K, V]) moveToFront(e *entry[K, V]) {
	if c.root.next == e {
		return
	}
	c.unlink(e)
	c.pushFront(e)
}

package lru

import "testing"

func TestEvictionOrder(t *testing.T) {
	c := New[string, string](2)
	c.Set("a", "1")
	c.Set("b", "2")
	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Fatalf("Get(a) = %q, %v; want 1, true", v, ok)
	}
	c.Set("c", "3")
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
	if got := c.Len(); got != 2 {
		t.Fatalf("Len() = %d; want 2", got)
	}
}

func TestOverwriteRefreshes(t *testing.T) {
	c := New[string, string](2)
	c.Set("a", "1")
	c.Set("b", "2")
	c.Set("a", "9")
	c.Set("c", "3")
	if v, ok := c.Get("a"); !ok || v != "9" {
		t.Fatalf("Get(a) = %q, %v; want 9, true", v, ok)
	}
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
}

func TestDelete(t *testing.T) {
	c := New[string, string](3)
	c.Set("x", "1")
	if !c.Delete("x") {
		t.Fatal("first Delete(x) = false; want true")
	}
	if c.Delete("x") {
		t.Fatal("second Delete(x) = true; want false")
	}
	if c.Len() != 0 {
		t.Fatalf("Len() = %d; want 0", c.Len())
	}
}

// Command app simulates an LRU cache driven by commands read from standard
// input. See SPEC.md for the protocol.
package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"

	"lru/internal/lru"
)

const bufferSize = 1 << 16

func main() {
	out := bufio.NewWriterSize(os.Stdout, bufferSize)
	err := run(os.Stdin, out)
	if ferr := out.Flush(); err == nil {
		err = ferr
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, "app:", err)
		os.Exit(1)
	}
}

// run reads the capacity header and then executes each command line.
func run(r io.Reader, w *bufio.Writer) error {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, bufferSize), 1<<30)
	if !sc.Scan() {
		return sc.Err()
	}
	capacity, err := strconv.Atoi(strings.TrimSpace(sc.Text()))
	if err != nil {
		return fmt.Errorf("invalid capacity: %w", err)
	}
	if capacity < 1 {
		return errors.New("capacity must be positive")
	}
	cache := lru.New[string, string](capacity)
	for sc.Scan() {
		execute(cache, sc.Bytes(), w)
	}
	return sc.Err()
}

// execute applies one command line to the cache. Blank or unrecognised lines
// are ignored.
func execute(cache *lru.Cache[string, string], line []byte, w *bufio.Writer) {
	cmd, rest, hasArg := bytes.Cut(line, []byte{' '})
	switch string(cmd) {
	case "SET":
		key, value, ok := bytes.Cut(rest, []byte{' '})
		if !hasArg || !ok {
			return
		}
		cache.Set(string(key), string(value))
	case "GET":
		if !hasArg {
			return
		}
		if v, ok := cache.Get(string(rest)); ok {
			writeLine(w, v)
		} else {
			writeLine(w, "NULL")
		}
	case "DEL":
		if !hasArg {
			return
		}
		if cache.Delete(string(rest)) {
			writeLine(w, "1")
		} else {
			writeLine(w, "0")
		}
	case "SIZE":
		w.WriteString(strconv.Itoa(cache.Len()))
		w.WriteByte('\n')
	}
}

// writeLine writes s followed by a newline. Write errors are sticky in
// bufio.Writer and surface when the writer is flushed.
func writeLine(w *bufio.Writer, s string) {
	w.WriteString(s)
	w.WriteByte('\n')
}
